from scipy.spatial.transform import Rotation, Slerp
counter=0
state=obs

def capture(res,label):
    global counter,state
    counter+=1; state=res
    res.save(str(OUT/f'{counter:03d}_{label}'))
    (OUT/'latest_meta.json').write_text(json.dumps(res.meta,indent=2))
    for cam,img in res.last.items(): Image.fromarray(img).save(OUT/f'latest_{cam}.png')
    np.savez(OUT/'latest_depth.npz',**res.last_depth)
    print('RESULT',label,{k:res.meta.get(k) for k in ['done','reason','control_steps','time_left_s','stopped','executed_rows','clipped']},flush=True)
    print('TCP',res.group('tcp_pose',now=True).round(5),'OPEN',res.group('gripper_opening',now=True).round(5),flush=True)
    return res

def nowq(): return state.group('joint_pos',now=True).copy()
def armq():
    q=nowq(); return np.r_[q[:7],q[8:15]]
def poses(): return state.group('tcp_pose',now=True).reshape(2,7).copy()
def move(targets,grips=None,duration=3.,label='move'):
    q0=nowq(); ik=r.ik(targets,seed=armq())
    print('IK',ik['ok'],ik.get('error'),flush=True)
    if not ik['ok']: return ik
    q1=q0.copy(); q1[:7]=ik['q'][:7]; q1[8:15]=ik['q'][7:]
    if grips is not None:
        for side,g in grips.items(): q1[7 if side=='R' else 15]=g
    n=int(round(duration*10)); a=np.linspace(q0,q1,n+1)[1:]
    return capture(r.submit('joint_position',a,dt=.1,video='mp4',video_fps=10,depth=True,note=label),label)
def grip(side,width,duration=1.,label='grip'):
    q0=nowq(); q1=q0.copy(); q1[7 if side=='R' else 15]=width
    return capture(r.submit('joint_position',np.linspace(q0,q1,int(duration*10)+1)[1:],dt=.1,video='mp4',depth=True,note=label),label)
def watch(seconds=.5,label='watch'):
    return capture(r.get_obs(seconds=seconds,video='mp4',depth=True),label)
def point(cam,u,v,res=None):
    res=res or state; C=res.meta['cameras'][cam]; K=np.array(C['intrinsic_cv']); E=np.array(C['extrinsic_cv']); d=res.last_depth[cam][v,u]
    return E[:,:3].T@(np.linalg.inv(K)@np.array([u,v,1.])*d-E[:,3])
